import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ request }) => {
  // Arrange: sign in as the member (a sign-in feature test, so USERS and PASSWORD are allowed)
  await expectStatus(
    await request.post("/api/auth/login", { data: { email: USERS.member, password: PASSWORD } }),
    200,
  );
  const before = await request.storageState();
  expect(before.cookies.map((c) => c.name), "session cookie set after sign in").toContain("session");

  // Act
  const response = await request.post("/api/auth/logout");

  // Assert
  await expectStatus(response, 204);
  const setCookie = response
    .headersArray()
    .filter((h) => h.name.toLowerCase() === "set-cookie")
    .map((h) => h.value)
    .find((v) => v.startsWith("session="));
  expect(setCookie, "logout sends a Set-Cookie for session").toBeDefined();
  expect(setCookie).toMatch(/^session=(""|);/);
  expect(setCookie?.toLowerCase()).toContain("max-age=0");
  const after = await request.storageState();
  expect(after.cookies.map((c) => c.name), "session cookie removed after sign out").not.toContain("session");
});
